window.MOTIF_CATALOG_CHUNKS[48]={"cards":[{"id":"MEJE-KW-002585","row_version":2,"title":"붉거나 이상한 달로 재앙을 예고하기","original":"Bad Moon Rising","aliases":[],"kind":"keyword","facet_id":"ML-F20","node_kind":null,"parent_id":null,"tag_path":["ML-F20"],"summary":"평소와 다른 색과 크기의 달이 떠오르며 큰 사건이 다가옴을 알린다. 하늘의 변화를 세계의 불길한 신호로 읽는 상징이다. 하늘의 징후와 함께 작은 떨림으로 거대한 위협을 알리기을 배치하면 위협을 느끼게 할 수 있다.","accent":"#85835C","tab":"#9A6A55","facet":"상징·이미지","bookmark":"분류축","entry_url":"cards/MEJE-KW-002585/index.html"},{"id":"MEJE-KW-002586","row_version":2,"title":"나쁜 소식을 좋게 포장해서 말하기","original":"Bad News in a Good Way","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"전해야 할 손해와 실패를 밝히면서도 표현과 순서를 바꿔 덜 심각하게 보이게 한다. 듣는 사람이 사실을 알게 되는 순간 포장의 의도도 드러난다. 사소한 이득을 내세우는 큰 불행에 사소한 좋은 소식을 덧붙이기와 말의 방향이 가깝다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-002586/index.html"},{"id":"MEJE-KW-002587","row_version":1,"title":"큰 불행에 사소한 좋은 소식을 덧붙이기","original":"Bad News, Irrelevant News","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"심각한 피해를 알린 뒤 거의 관계없는 작은 이득을 좋은 소식이라고 전한다. 두 정보의 크기 차이가 상황의 절망과 화자의 감각을 드러낸다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-002587/index.html"},{"id":"MEJE-KW-002588","row_version":1,"title":"오소리를 거칠게 그리는 동물 이미지","original":"Bad Ol' Badger","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":null,"parent_id":null,"tag_path":["ML-F12"],"summary":"작품 속 오소리가 공격적이고 고집 센 동물로 반복해서 묘사된다. 실제 동물의 성질을 단정하기보다 이야기에서 맡은 역할과 이미지를 다룬다.","accent":"#62816F","tab":"#9A6A55","facet":"존재·종족","bookmark":"분류축","entry_url":"cards/MEJE-KW-002588/index.html"},{"id":"MEJE-KW-002589","row_version":1,"title":"위로하려고 꺼낸 이야기가 더 불길하기","original":"Bad Omen Anecdote","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"긴장한 사람을 달래려던 인물이 비슷한 사건의 나쁜 결말을 들려준다. 위로의 의도와 내용의 방향이 어긋나 불안이나 웃음이 생긴다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-002589/index.html"},{"id":"MEJE-KW-002590","row_version":1,"title":"동물에게 잔혹한 행동으로 악역을 알리기","original":"Bad People Abuse Animals","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":null,"parent_id":null,"tag_path":["ML-F06"],"summary":"인물이 방어하기 어려운 동물을 함부로 대하는 장면으로 위험한 성향을 보여 준다. 폭력을 장식으로 쓰지 않고 그 행동이 주변에 남기는 의미를 살핀다.","accent":"#88734E","tab":"#9A6A55","facet":"서사 기능","bookmark":"분류축","entry_url":"cards/MEJE-KW-002590/index.html"},{"id":"MEJE-KW-002591","row_version":2,"title":"불길한 힘을 받아 악행에 쓰는 인물","original":"Bad Powers, Bad People","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"손에 넣은 능력이 남을 해치기 쉬운 성질을 지녔고 사용자가 그 방향을 선택한다. 능력의 외형만이 아니라 쓰기로 한 사람의 판단이 중요하다. 같은 힘을 가진 이가 불길한 힘을 선한 목적에 쓰려는 인물을 선택할 수도 있다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-002591/index.html"},{"id":"MEJE-KW-002592","row_version":2,"title":"불길한 힘을 선한 목적에 쓰려는 인물","original":"Bad Powers, Good People","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"위협적으로 보이는 능력을 가진 인물이 사람을 돕는 방법을 찾는다. 힘의 성질과 사용자의 의도를 분리해 보여 준다. 힘의 외형만으로 불길한 힘을 받아 악행에 쓰는 인물라고 단정하지 않는다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-002592/index.html"},{"id":"MEJE-KW-002593","row_version":1,"title":"과거에서 온 사람이 현재를 실망스럽게 보기","original":"Bad Present","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":null,"parent_id":null,"tag_path":["ML-F14"],"summary":"먼 과거의 인물이 현재에 와서 자신이 바라던 발전과 다른 현실을 본다. 익숙한 일상을 낯선 가치 기준으로 다시 바라보게 한다.","accent":"#68838D","tab":"#9A6A55","facet":"시공간·환경","bookmark":"분류축","entry_url":"cards/MEJE-KW-002593/index.html"},{"id":"MEJE-KW-002594","row_version":2,"title":"이기적인 동기로 좋은 일을 하기","original":"Bad Reason to Do Good","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"남을 돕는 행동을 하면서도 칭찬과 인정 같은 자기 이익을 주된 이유로 삼는다. 행동의 결과와 동기에 대한 평가는 같은 방향일 필요가 없다. 동기가 다른 이에게 당장의 해결을 맡기는 주인공 대신 악당이 꺼리는 일을 해치우기와 구분한다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-002594/index.html"},{"id":"MEJE-KW-002595","row_version":1,"title":"혹평을 빌미로 특혜를 요구하기","original":"Bad Review Threat","aliases":[],"kind":"keyword","facet_id":"ML-F08","node_kind":null,"parent_id":null,"tag_path":["ML-F08"],"summary":"인물이 나쁜 평가를 남기겠다고 위협해 가게나 창작자에게 원하는 대우를 얻으려 한다. 의견을 말할 권한이 협상의 압박으로 바뀌는 상황이다.","accent":"#936E72","tab":"#9A6A55","facet":"갈등·장애","bookmark":"분류축","entry_url":"cards/MEJE-KW-002595/index.html"},{"id":"MEJE-KW-002596","row_version":2,"title":"도움을 주는 척 접근하는 위험한 사람","original":"Bad Samaritan","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"길을 잃거나 다친 인물에게 친절을 베푸는 사람이 다른 의도를 숨긴다. 도움을 거절하기 어려운 상황을 악용해 신뢰를 위협으로 바꾼다. 친숙한 외형이 위협으로 바뀌는 축제의 산타가 위협적인 존재로 바뀌기와 위험의 출발점이 닮았다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-002596/index.html"},{"id":"MEJE-KW-002597","row_version":1,"title":"축제의 산타가 위협적인 존재로 바뀌기","original":"Bad Santa","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"선물을 주는 친근한 산타의 모습을 범죄자나 괴물의 외형에 씌운다. 기대한 안전함과 실제 행동의 차이가 공포나 풍자를 만든다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-002597/index.html"},{"id":"MEJE-KW-002598","row_version":2,"title":"남의 취향을 공개적으로 깎아내리기","original":"Bad Taste Call-Out","aliases":[],"kind":"keyword","facet_id":"ML-F26","node_kind":null,"parent_id":null,"tag_path":["ML-F26"],"summary":"자신과 다른 작품 취향을 수준 낮다고 몰아붙여 상대를 공동체 밖으로 밀어낸다. 평가의 내용보다 취향으로 사람의 서열을 정하는 행동이 핵심이다.","accent":"#9D806B","tab":"#9A6A55","facet":"공연·참여·팬덤","bookmark":"분류축","entry_url":"cards/MEJE-KW-002598/index.html"},{"id":"MEJE-KW-002599","row_version":1,"title":"마시기 힘들 만큼 맛없는 커피","original":"Bad to the Last Drop","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":null,"parent_id":null,"tag_path":["ML-F16"],"summary":"평범한 휴식이 될 커피가 지나치게 쓰거나 엉망으로 만들어져 인물의 하루를 더 힘들게 한다. 맛의 실패가 장소의 처지나 관계의 무성의를 보여 준다.","accent":"#8E8263","tab":"#9A6A55","facet":"사물·도구·자원","bookmark":"분류축","entry_url":"cards/MEJE-KW-002599/index.html"},{"id":"MEJE-KW-002600","row_version":2,"title":"작은 떨림으로 거대한 위협을 알리기","original":"Bad Vibrations","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"잔 속의 물결이나 바닥의 물건이 먼저 흔들리고 나서 큰 존재가 다가옴을 알게 된다. 위협의 몸을 보여 주기 전에 규모와 거리를 느끼게 한다. 작은 떨림은 붉거나 이상한 달로 재앙을 예고하기이 떠오르기 전의 신호가 될 수 있다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-002600/index.html"},{"id":"MEJE-KW-002601","row_version":1,"title":"뼈를 무기로 사용하기","original":"Bad with the Bone","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":null,"parent_id":null,"tag_path":["ML-F16"],"summary":"해골이나 커다란 동물의 뼈를 손에 쥐고 공격 도구로 쓴다. 무기가 만들어진 재료가 죽음과 생존의 분위기를 동시에 전한다.","accent":"#8E8263","tab":"#9A6A55","facet":"사물·도구·자원","bookmark":"분류축","entry_url":"cards/MEJE-KW-002601/index.html"},{"id":"MEJE-KW-002602","row_version":1,"title":"자기 몸의 평범한 변화를 낯설어하기","original":"Baffled by Own Biology","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"처음 겪는 신체의 변화나 기능을 인물이 이상한 현상으로 오해한다. 몸이 달라진 이유와 충분한 설명을 듣지 못한 환경이 당혹감을 만든다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-002602/index.html"},{"id":"MEJE-KW-002603","row_version":2,"title":"안이 겉보다 큰 가방","original":"Bag of Holding","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":null,"parent_id":null,"tag_path":["ML-F16"],"summary":"작은 가방 속에 외형보다 훨씬 넓은 저장 공간이 있다. 무엇을 넣을 수 있고 무게가 어떻게 바뀌는지가 세계의 물리 규칙을 드러낸다. 한 사람의 무한한 수납과 여러 사람이 쓰는 팀원이 하나의 소지품 목록을 공유하기는 다른 규칙이다.","accent":"#8E8263","tab":"#9A6A55","facet":"사물·도구·자원","bookmark":"분류축","entry_url":"cards/MEJE-KW-002603/index.html"},{"id":"MEJE-KW-002604","row_version":1,"title":"자루를 씌워 사람을 끌고 가기","original":"Bag of Kidnapping","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"가해자가 큰 자루로 대상을 가려 움직임과 시야를 제한한 채 데려간다. 위협받는 사람의 관점과 이후의 구조 과정을 중심에 둔다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-002604/index.html"},{"id":"MEJE-KW-002605","row_version":2,"title":"팀원이 하나의 소지품 목록을 공유하기","original":"Bag of Sharing","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"여러 인물이 각자의 가방이 아니라 공통 창고에서 물건을 꺼내 쓴다. 관리가 간단해지는 대신 누가 무엇을 소유하는지가 흐려진다. 공동 자원의 편리함도 후속작에서 이전 소지품을 모두 잃기에서는 잃어버린다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-002605/index.html"},{"id":"MEJE-KW-002606","row_version":2,"title":"후속작에서 이전 소지품을 모두 잃기","original":"Bag of Spilling","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"지난 이야기에서 모은 장비나 능력이 새 출발에 앞서 사라진다. 연속된 이야기의 성취와 새 게임의 성장 곡선을 맞추려는 규칙이다. 사라진 물건에 안이 겉보다 큰 가방 같은 장비가 포함될 수 있다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-002606/index.html"},{"id":"MEJE-KW-002607","row_version":1,"title":"편지가 산더미처럼 쌓여 여론을 보여 주기","original":"Bags of Letters","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"인물에게 도착한 수많은 편지를 한 화면에 쌓아 보낸 사람들의 규모를 나타낸다. 몇 통의 내용보다 눈에 보이는 양이 사회적 반응을 전달한다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-002607/index.html"},{"id":"MEJE-KW-002608","row_version":1,"title":"바게트를 즉석 무기로 쓰기","original":"Baguette Beatdown","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"인물이 손에 든 긴 빵으로 위기를 막거나 우스운 싸움을 벌인다. 먹을 것을 무기로 바꾸는 발상의 간격이 장면의 희극성을 만든다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-002608/index.html"},{"id":"MEJE-KW-002609","row_version":1,"title":"보석금만 내면 사건이 끝난 듯 그리기","original":"Bail Equals Freedom","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"작품이 보석금을 낸 인물의 이후 절차를 생략하고 법적 문제가 모두 사라진 듯 진행한다. 극적 편의를 위한 묘사이며 실제 제도 설명으로 취급하지 않는다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-002609/index.html"},{"id":"MEJE-KW-002610","row_version":2,"title":"예상한 말과 다른 뜻으로 끝나는 반전","original":"Bait-and-Switch","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"말이나 행동의 앞부분이 한 결론을 예고하지만 끝에서 전혀 다른 뜻으로 바뀐다. 앞서 놓인 단서를 다시 읽게 만드는 구조다. 기대가 뒤집히는 게임 장면으로 예고한 보스 대신 진짜 보스가 등장하기가 있다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-002610/index.html"},{"id":"MEJE-KW-002611","row_version":2,"title":"비밀을 안다는 말에 엉뚱한 잘못을 고백하기","original":"Bait-and-Switch Accusation","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"상대가 무엇을 알아냈는지 확인하지 않은 인물이 다른 비밀부터 털어놓는다. 막연한 추궁이 뜻밖의 새 정보를 드러낸다. 비밀에 대한 추측을 이용한 예상한 말과 다른 뜻으로 끝나는 반전의 한 방식이다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-002611/index.html"},{"id":"MEJE-KW-002612","row_version":2,"title":"예고한 보스 대신 진짜 보스가 등장하기","original":"Bait-and-Switch Boss","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"맞설 상대라고 생각한 적이 무대에서 밀려나고 더 큰 위협이 그 자리를 차지한다. 전투의 시작 자체가 상대의 서열을 뒤집는다. 보스의 정체를 바꾸는 예상한 말과 다른 뜻으로 끝나는 반전이다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-002612/index.html"},{"id":"MEJE-KW-002613","row_version":2,"title":"첫인상과 전혀 다른 인물 소개","original":"Bait-and-Switch Character Intro","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"처음 등장하는 인물의 그림자와 행동이 특정 성격을 예고하지만 곧 반대 면이 드러난다. 짧은 소개 속에서 관객의 분류를 다시 쓰게 한다. 첫인상을 바꾸는 예상한 말과 다른 뜻으로 끝나는 반전이다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-002613/index.html"},{"id":"MEJE-KW-002614","row_version":2,"title":"칭찬처럼 시작해 모욕으로 끝내는 말","original":"Bait-and-Switch Comment","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"상대에게 호의를 보이는 듯한 문장을 이어 가다가 마지막 단어에서 공격으로 바꾼다. 듣는 사람이 안심한 순간 앞부분의 뜻도 뒤집힌다. 문장 안에서 기대를 바꾸는 예상한 말과 다른 뜻으로 끝나는 반전이다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-002614/index.html"},{"id":"MEJE-KW-002615","row_version":2,"title":"비교의 대상을 마지막에 바꿔 웃기기","original":"Bait-and-Switch Comparison","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"둘을 견주는 문장을 시작할 때 예상한 속성을 끝에서 반대쪽 대상에 붙인다. 비교의 틀은 유지하면서 평가의 방향을 뒤집는다. 비교의 방향을 돌리는 예상한 말과 다른 뜻으로 끝나는 반전이다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-002615/index.html"},{"id":"MEJE-KW-002616","row_version":2,"title":"걱정하는 척하다 자신을 걱정하기","original":"Bait-and-Switch Compassion","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"누군가의 고통을 안타까워하는 말처럼 시작하지만 끝에서 화자가 자기 손해만 걱정했음이 드러난다. 동정의 형식과 실제 관심이 어긋난다. 동정하는 사람을 바꾸는 예상한 말과 다른 뜻으로 끝나는 반전이다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-002616/index.html"},{"id":"MEJE-KW-002617","row_version":2,"title":"오프닝이 실제 작품과 다른 기대를 주기","original":"Bait-and-Switch Credits","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"첫 영상의 분위기와 인물 관계가 본편에서 펼쳐지는 이야기와 크게 다르다. 제목 화면만 보고 예상한 장르를 본편이 바꿔 놓는다. 오프닝과 본편의 간격을 이용한 예상한 말과 다른 뜻으로 끝나는 반전이다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-002617/index.html"},{"id":"MEJE-KW-002618","row_version":2,"title":"총성이 들렸지만 다른 사람이 맞기","original":"Bait-and-Switch Gunshot","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"위협받는 인물 앞에서 총성이 나지만 잠시 결과를 감춘 뒤 예상 밖의 대상이 맞았음을 보여 준다. 소리와 정보의 시간차가 긴장을 만든다. 소리 뒤의 결과를 늦게 밝히는 예상한 말과 다른 뜻으로 끝나는 반전이다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-002618/index.html"},{"id":"MEJE-KW-002619","row_version":4,"title":"성소수자 관계를 암시만 하고 거두기","original":"Bait-and-Switch Lesbians","aliases":[],"kind":"keyword","facet_id":"ML-F30","node_kind":null,"parent_id":null,"tag_path":["ML-F30"],"summary":"작품이 두 여성의 친밀함을 관객의 관심을 끄는 요소로 제시한 뒤 관계의 가능성을 설명 없이 지운다. 표현의 기대와 실제 서사가 어긋나는 수용 문제다. 관객의 관계 기대를 이용한 예상한 말과 다른 뜻으로 끝나는 반전으로 읽을 수 있다.","accent":"#8B817D","tab":"#9A6A55","facet":"대상·수용맥락","bookmark":"분류축","entry_url":"cards/MEJE-KW-002619/index.html"},{"id":"MEJE-KW-002620","row_version":2,"title":"멋지게 들리던 공연이 실제로는 엉망이기","original":"Bait-and-Switch Performance","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":null,"parent_id":null,"tag_path":["ML-F24"],"summary":"공연자의 귀에는 훌륭하게 들리던 무대가 관객의 시점으로 바뀌자 어긋난 소리로 드러난다. 주관적 체험과 외부 평가의 간격을 소리로 보여 준다. 듣는 위치를 바꾸는 예상한 말과 다른 뜻으로 끝나는 반전이다.","accent":"#8A7893","tab":"#9A6A55","facet":"소리·음악","bookmark":"분류축","entry_url":"cards/MEJE-KW-002620/index.html"},{"id":"MEJE-KW-002621","row_version":2,"title":"감동적인 말처럼 시작해 사익으로 돌리기","original":"Bait-and-Switch Sentiment","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"공동의 희망을 말하는 듯한 인물이 문장 끝에서 자기 이익을 내세운다. 듣는 사람의 감정이 올라간 순간 화자의 진짜 목적이 드러난다. 감동적인 말의 뜻을 바꾸는 예상한 말과 다른 뜻으로 끝나는 반전이다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-002621/index.html"},{"id":"MEJE-KW-002622","row_version":2,"title":"정체를 드러내자 평범한 그림자였기","original":"Bait-and-Switch Silhouette","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"모양만 보일 때 특별한 존재처럼 보이던 그림자가 빛이나 시점의 변화로 평범한 사물임이 밝혀진다. 화면이 숨긴 정보가 웃음의 조건이다. 윤곽의 정체를 바꾸는 시각적 예상한 말과 다른 뜻으로 끝나는 반전이다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-002622/index.html"},{"id":"MEJE-KW-002623","row_version":2,"title":"극단적 선택을 암시했다가 다른 행동으로 풀기","original":"Bait-and-Switch Suicide","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"인물이 위험한 선택을 앞둔 것처럼 보이는 장면에서 다른 목적이 밝혀진다. 관객의 불안을 이용하는 만큼 인물의 고통을 가볍게 소비하지 않도록 맥락을 살핀다. 위험에 대한 기대를 돌리는 예상한 말과 다른 뜻으로 끝나는 반전이다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-002623/index.html"},{"id":"MEJE-KW-002624","row_version":2,"title":"긴 시간이 지난 듯 보였지만 잠깐이기","original":"Bait-and-Switch Time Skip","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"큰 변화가 생긴 화면으로 시간이 많이 흘렀다고 느끼게 한 뒤 실제로는 아주 짧은 시간이 지났음을 밝힌다. 시간의 체감과 사건의 속도를 뒤집는다. 시간의 길이를 바꾸는 예상한 말과 다른 뜻으로 끝나는 반전이다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-002624/index.html"},{"id":"MEJE-KW-002625","row_version":2,"title":"폭군처럼 보인 새 지도자가 의외로 온건하기","original":"Bait-and-Switch Tyrant","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"새로 권력을 잡은 인물이 위협적인 말과 자세를 보이지만 실제 행동은 예상보다 배려 깊다. 권위에 대한 첫인상과 통치의 결과가 어긋난다. 지도자에 대한 첫 판단을 바꾸는 예상한 말과 다른 뜻으로 끝나는 반전이다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-002625/index.html"},{"id":"MEJE-KW-002626","row_version":3,"title":"관객의 분신인 줄 알았던 인물이 독자적으로 움직이기","original":"Bait Audience Surrogate","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"관객이 자신을 투영하기 쉽도록 소개된 인물이 갈수록 뚜렷한 욕망과 비밀을 드러낸다. 비워 둔 자리처럼 보였던 인물이 자기 서사를 되찾는다. 인물의 첫인상을 다시 쓰는 첫인상과 전혀 다른 인물 소개와 서사적 기능이 가깝다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-002626/index.html"},{"id":"MEJE-KW-002627","row_version":2,"title":"호감 가던 인물의 악의가 드러나기","original":"Bait the Dog","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"친근한 행동으로 관객의 신뢰를 얻은 인물이 뒤늦게 타인을 해칠 의도를 드러낸다. 앞선 호의를 새 정보로 다시 해석하게 한다. 선한 얼굴로 접근하는 도움을 주는 척 접근하는 위험한 사람와 호감의 활용을 비교할 수 있다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-002627/index.html"},{"id":"MEJE-KW-002628","row_version":2,"title":"서로 다른 정보로 내부 제보자를 찾기","original":"Bait the Mole","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"의심받는 사람마다 조금씩 다른 정보를 주고 어느 내용이 밖으로 나오는지 지켜본다. 새어나간 말의 모양이 내부 연결을 가리킨다. 누가 무엇을 아는지 떠보는 비밀을 안다는 말에 엉뚱한 잘못을 고백하기와 정보의 차이를 이용한다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-002628/index.html"},{"id":"MEJE-KW-002629","row_version":2,"title":"오래 산 고양이가 요괴가 되는 전승","original":"Bakeneko and Nekomata","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":null,"parent_id":null,"tag_path":["ML-F12"],"summary":"오래 살거나 특별한 일을 겪은 고양이가 사람의 말과 변신 능력을 얻는 일본 전승의 존재. 꼬리가 갈라진 네코마타를 포함해 작품마다 규칙이 다르게 쓰인다.","accent":"#62816F","tab":"#9A6A55","facet":"존재·종족","bookmark":"분류축","entry_url":"cards/MEJE-KW-002629/index.html"},{"id":"MEJE-KW-002630","row_version":1,"title":"거리의 아이들을 정보망으로 쓰는 탐정","original":"Baker Street Regular","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"탐정이 도시 곳곳을 드나드는 아이들에게 소식을 모아 달라고 부탁한다. 눈에 잘 띄지 않는 생활 경로가 수사의 자원이 된다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-002630/index.html"},{"id":"MEJE-KW-002631","row_version":1,"title":"악몽을 먹는 바쿠","original":"Baku","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":null,"parent_id":null,"tag_path":["ML-F12"],"summary":"잠든 사람의 나쁜 꿈을 먹어 준다고 전해지는 동아시아의 상상 동물. 작품에서는 잠과 기억에 개입하는 존재로 변주된다.","accent":"#62816F","tab":"#9A6A55","facet":"존재·종족","bookmark":"분류축","entry_url":"cards/MEJE-KW-002631/index.html"},{"id":"MEJE-KW-002632","row_version":2,"title":"선과 악이 함께 있어야 유지되는 세계","original":"Balance Between Good and Evil","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"두 대립하는 힘이 어느 한쪽의 완전한 승리 없이 균형을 이뤄야 한다는 세계 규칙. 선악의 가치 판단과 우주의 작동 원리를 작품 안에서 어떻게 연결하는지가 중요하다. 균형 자체를 거부하는 악과의 균형을 거부하는 인물는 이 규칙을 비판한다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-002632/index.html"},{"id":"MEJE-KW-002633","row_version":2,"title":"게임의 약한 선택지를 상향 조정하기","original":"Balance Buff","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"게임이 업데이트되며 성능이 낮던 인물이나 도구의 수치와 기능을 높인다. 선택지 사이의 격차를 줄이려는 운영 판단이 플레이 경험을 바꾼다. 네 가지 선택지 가운데 약한 쪽을 고치는 균형·화력·기술·변칙의 네 선택지에 영향을 준다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-002633/index.html"},{"id":"MEJE-KW-002634","row_version":1,"title":"여러 연애 후보의 비중을 고르게 두기","original":"Balanced Harem","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"한 인물을 둘러싼 여러 관계에 비슷한 시간과 사건을 배분한다. 특정 결말을 늦추는 구조가 관계의 성장 방식에도 영향을 준다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-002634/index.html"},{"id":"MEJE-KW-002635","row_version":3,"title":"악과의 균형을 거부하는 인물","original":"Balance Is Not Good","aliases":[],"kind":"keyword","facet_id":"ML-F18","node_kind":null,"parent_id":null,"tag_path":["ML-F18"],"summary":"선과 악이 같게 남아야 한다는 세계의 주장을 인물이 받아들이지 않는다. 피해를 막아야 할 때 균형이라는 말이 무엇을 정당화하는지 묻는다. 선과 악이 함께 있어야 유지되는 세계이라는 말이 피해를 방치하는 이유인지 묻는다.","accent":"#7E8070","tab":"#9A6A55","facet":"주제·가치","bookmark":"분류축","entry_url":"cards/MEJE-KW-002635/index.html"},{"id":"MEJE-KW-002636","row_version":2,"title":"국가 사이의 세력 균형","original":"Balance of Power","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15"],"summary":"여러 국가가 한쪽의 압도적 우세를 막기 위해 동맹과 견제를 조정한다. 힘의 분포가 변할 때 전쟁과 협상의 선택지도 함께 달라진다. 국가 사이의 전략인 선과 악이 함께 있어야 유지되는 세계과 우주 규칙을 구분한다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"분류축","entry_url":"cards/MEJE-KW-002636/index.html"},{"id":"MEJE-KW-002637","row_version":2,"title":"균형·화력·기술·변칙의 네 선택지","original":"Balance, Power, Skill, Gimmick","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"게임이 네 캐릭터나 장비를 서로 다른 장점으로 나눠 선택하게 한다. 익숙한 균형형을 기준으로 특화형과 변칙형의 위험을 비교할 수 있다. 선택지 하나를 줄이면 균형형·속도형·힘형의 세 인물와 역할 구성이 닮는다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-002637/index.html"},{"id":"MEJE-KW-002638","row_version":2,"title":"균형형·속도형·힘형의 세 인물","original":"Balance, Speed, Strength Trio","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"세 플레이 인물을 고른 성능과 빠른 움직임, 높은 화력으로 나눠 제시한다. 서로 다른 조작감이 팀 구성과 첫 선택에 의미를 준다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-002638/index.html"},{"id":"MEJE-KW-002639","row_version":2,"title":"죽음을 대신 떠안을 사람을 찾기","original":"Balancing Death's Books","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"죽음이 정해진 사람을 살리려면 다른 생명이 대가가 되어야 하는 세계 규칙. 누구에게 그 값을 요구할 권리가 있는지가 사건의 윤리적 갈등이 된다. 목숨을 맞바꾸는 거래는 선과 악이 함께 있어야 유지되는 세계의 잔혹한 적용이 될 수 있다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-002639/index.html"},{"id":"MEJE-KW-002640","row_version":3,"title":"발코니를 따라 방에서 빠져나가기","original":"Balcony Escape","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"문을 사용할 수 없을 때 인물이 창 밖으로 나가 발코니나 난간을 따라 이동한다. 열린 공간과 추락의 가능성이 탈출을 긴장되게 만든다. 같은 장소를 로맨스에 쓰는 발코니 아래에서 마음을 전하기와 위험의 종류가 다르다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-002640/index.html"},{"id":"MEJE-KW-002641","row_version":2,"title":"높은 발코니에서 군중에게 연설하기","original":"Balcony Speech","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"지도자가 높은 발코니에 서서 아래에 모인 사람들에게 말을 건넨다. 높이의 차이가 권위와 거리감을 시각적으로 드러낸다. 발코니가 개인의 마음을 전하는 곳이면 발코니 아래에서 마음을 전하기가 된다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-002641/index.html"},{"id":"MEJE-KW-002642","row_version":1,"title":"발코니 아래에서 마음을 전하기","original":"Balcony Wooing Scene","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"한 인물이 위층 발코니나 창가의 상대에게 노래나 말로 애정을 고백한다. 물리적인 높이와 접근의 어려움이 관계의 간격을 보여 준다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-002642/index.html"},{"id":"MEJE-KW-002643","row_version":2,"title":"민머리로 강한 인상을 주기","original":"Bald Head of Toughness","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"짧게 깎은 머리나 민머리를 인물의 단단한 외형으로 사용한다. 외모가 실제 성격이나 능력을 보증하지 않는다는 점과 함께 읽는다. 같은 민머리를 민머리로 신비로운 인물을 나타내기에서는 다른 상징으로 쓴다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-002643/index.html"},{"id":"MEJE-KW-002644","row_version":2,"title":"민머리로 신비로운 인물을 나타내기","original":"Bald Mystic","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"머리카락이 없는 외형을 수행자나 초자연적 존재의 이미지에 연결한다. 특정 종교인의 실제 모습을 하나로 단정하지 않고 시각적 관습으로 다룬다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-002644/index.html"},{"id":"MEJE-KW-002645","row_version":3,"title":"탈모 때문에 자신감을 잃는 인물","original":"Baldness Angst","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"머리카락의 변화가 인물에게 불안이나 상실감을 준다. 주변의 시선과 자기 이미지가 어떻게 엇갈리는지가 중요한 갈등이다. 자기 이미지의 불안에 탈모를 놀림거리로 삼기까지 겹치면 상처가 커진다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-002645/index.html"},{"id":"MEJE-KW-002646","row_version":2,"title":"머리카락이 없으면 병들었다고 암시하기","original":"Baldness Means Sickness","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"작품이 탈모를 심각한 질병의 즉각적인 표지로 사용한다. 여러 원인을 한 가지 이미지로 묶는 단순화가 인물에게 미치는 영향도 살핀다. 단순한 질병 이미지가 탈모 때문에 자신감을 잃는 인물를 키울 수 있다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-002646/index.html"},{"id":"MEJE-KW-002647","row_version":1,"title":"탈모를 놀림거리로 삼기","original":"Baldness Mockery","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15"],"summary":"인물의 머리 모양을 웃음이나 모욕의 대상으로 삼는다. 놀리는 사람의 태도와 당사자의 반응을 구분해 표현할 수 있다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"분류축","entry_url":"cards/MEJE-KW-002647/index.html"},{"id":"MEJE-KW-002648","row_version":3,"title":"민머리로 지도자의 권위를 보이기","original":"Bald of Authority","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"지도자의 머리 모양을 강한 실루엣으로 사용해 침착함이나 위엄을 나타낸다. 외모가 통치 능력을 증명하는 것은 아니므로 화면의 관습으로 구분한다. 같은 외형을 민머리를 악역의 표지로 삼기에서는 반대의 인상으로 쓴다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-002648/index.html"},{"id":"MEJE-KW-002649","row_version":1,"title":"민머리를 악역의 표지로 삼기","original":"Bald of Evil","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"머리카락이 없는 외형을 인물의 위험성과 바로 연결한다. 행동을 보기 전에 외모로 선악을 판단하게 만드는 시각적 관습이다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-002649/index.html"},{"id":"MEJE-KW-002650","row_version":1,"title":"발칸 출신 인물을 범죄자로 단정하는 묘사","original":"Balkan Bastard","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"동남유럽 출신이라는 사실만으로 폭력과 부패를 인물의 공통 성질처럼 부여한다. 특정 지역의 다양한 삶을 범죄 이미지 하나로 줄이는 고정관념을 비판적으로 다룬다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-002650/index.html"},{"id":"MEJE-KW-002651","row_version":1,"title":"큰 나라가 여러 나라로 갈라진 대체 역사","original":"Balkanize Me","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"한 국가가 전쟁이나 분리 운동 뒤 여러 정치체로 나뉜 세계를 설정한다. 국경의 변화가 언어와 이동, 동맹의 규칙까지 바꾼다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-002651/index.html"},{"id":"MEJE-KW-002652","row_version":3,"title":"소환된 영이 명령을 거부하기","original":"Balking Summoned Spirit","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"부름에 응한 영적 존재가 소환자의 요구를 듣고 협조하지 않거나 조건을 내건다. 소환 능력과 실제 통제권이 같지 않다는 세계 규칙이다. 소환자의 뜻을 따르지 않는 영을 의식으로 존재를 다른 곳에 내쫓기로 내보내려 할 수도 있다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-002652/index.html"},{"id":"MEJE-KW-002653","row_version":2,"title":"성 노동자의 삶을 노래하는 발라드","original":"Ballad of a Sex Worker","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":null,"parent_id":null,"tag_path":["ML-F24"],"summary":"성 노동을 하는 인물의 관계와 생계를 노래의 화자 또는 주제로 삼는다. 직업을 비극이나 구원의 장치로만 줄이지 않고 인물의 목소리가 있는지 살핀다. 인물의 생활 조건은 성 노동자들의 보호 조직 같은 공동 규칙과도 연결된다.","accent":"#8A7893","tab":"#9A6A55","facet":"소리·음악","bookmark":"분류축","entry_url":"cards/MEJE-KW-002653/index.html"},{"id":"MEJE-KW-002654","row_version":1,"title":"제목에 발라드를 붙여 정서를 예고하기","original":"Ballad of X","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"작품 제목에 발라드라는 말을 넣어 노래와 이야기, 회상과 애도의 느낌을 미리 건넨다. 제목의 정서가 실제 내용과 맞거나 어긋나는 방식도 의미가 된다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-002654/index.html"},{"id":"MEJE-KW-002655","row_version":1,"title":"물개가 공을 코에 올리고 묘기를 부리기","original":"Ball-Balancing Seal","aliases":[],"kind":"keyword","facet_id":"ML-F26","node_kind":null,"parent_id":null,"tag_path":["ML-F26"],"summary":"물개나 바다사자가 둥근 물건을 코끝에 올려 장난이나 공연처럼 보여 준다. 동물의 능력을 귀여움의 장면으로 쓰는 연출이다.","accent":"#9D806B","tab":"#9A6A55","facet":"공연·참여·팬덤","bookmark":"분류축","entry_url":"cards/MEJE-KW-002655/index.html"},{"id":"MEJE-KW-002656","row_version":1,"title":"공을 쏘는 장치가 무기로 쓰이기","original":"Ball Cannon","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":null,"parent_id":null,"tag_path":["ML-F16"],"summary":"스포츠 연습용 발사 장치를 전투나 방어에 전용한다. 일상적 도구가 위험한 상황에서 다른 역할을 갖는다.","accent":"#8E8263","tab":"#9A6A55","facet":"사물·도구·자원","bookmark":"분류축","entry_url":"cards/MEJE-KW-002656/index.html"},{"id":"MEJE-KW-002657","row_version":1,"title":"발레가 중심이 되는 특별 회차","original":"Ballet Episode","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"평소 다른 활동을 하던 인물들이 한 회차 동안 발레 수업이나 공연에 참여한다. 춤의 연습과 무대가 관계의 변화를 드러내는 사건이 된다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-002657/index.html"},{"id":"MEJE-KW-002658","row_version":2,"title":"큰 공을 타고 통통 뛰며 이동하기","original":"Ball Hopping","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"손잡이가 달린 탄성 공을 타고 뛰어 이동하는 모습을 과장한다. 이동 수단의 어색함이 속도와 자세의 웃음을 만든다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-002658/index.html"},{"id":"MEJE-KW-002659","row_version":2,"title":"뼈를 던져 공격하기","original":"Ballistic Bone","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":null,"parent_id":null,"tag_path":["ML-F16"],"summary":"해골이나 괴물이 뼈를 원거리 공격의 탄환처럼 던진다. 몸의 일부인지 따로 마련한 무기인지에 따라 존재의 규칙이 달라진다. 뼈를 던지는 전투와 거대한 전투 도끼로 힘을 과시하기는 무기의 재료와 인상이 다르다.","accent":"#8E8263","tab":"#9A6A55","facet":"사물·도구·자원","bookmark":"분류축","entry_url":"cards/MEJE-KW-002659/index.html"},{"id":"MEJE-KW-002660","row_version":1,"title":"건네받은 상품으로 점원을 위협하기","original":"Ballistic Discount","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"거래하는 척 물건을 받아 든 인물이 그것으로 점원을 겁준다. 판매 절차에 기대한 신뢰가 돌연 위험으로 바뀌는 사건이다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-002660/index.html"},{"id":"MEJE-KW-002661","row_version":1,"title":"빛의 구체가 되어 이동하기","original":"Ball of Light Transformation","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"인물이 몸을 작은 빛덩이로 바꿔 날거나 좁은 곳을 통과한다. 빛 상태에서의 감각과 상처 여부가 변신 능력의 경계를 정한다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-002661/index.html"},{"id":"MEJE-KW-002662","row_version":2,"title":"풍선 여러 개에 매달려 날아가기","original":"Balloonacy","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"인물이나 물건이 많은 풍선에 끌려 공중으로 떠오른다. 실제 부력의 계산보다 가벼운 동화적 이동을 보여 주는 장면이다. 공중 이동의 불안은 새가 풍선을 터뜨리기로 커질 수 있다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-002662/index.html"},{"id":"MEJE-KW-002663","row_version":1,"title":"많이 먹자 배가 풍선처럼 부풀기","original":"Balloon Belly","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"음식을 먹은 인물의 배가 순식간에 둥글게 커졌다가 다시 줄어든다. 양을 과장해 포만감이나 소동을 시각적으로 나타낸다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-002663/index.html"},{"id":"MEJE-KW-002664","row_version":2,"title":"새가 풍선을 터뜨리기","original":"Balloon-Bursting Bird","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"공중에 뜬 풍선 가까이 새가 날아와 부리나 발톱으로 터뜨린다. 가벼운 비행 장면이 갑자기 추락 위험으로 바뀐다. 풍선에 메시지를 매달아 보내기에 쓰인 풍선도 경로에서 터질 수 있다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-002664/index.html"},{"id":"MEJE-KW-002665","row_version":2,"title":"풍선에 메시지를 매달아 보내기","original":"Balloon Delivery","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"편지나 작은 물건을 풍선에 달아 멀리 보내려 한다. 받는 사람과 경로를 통제하기 어렵다는 점이 우연한 도착의 이야기가 된다. 사람까지 띄우는 풍선 여러 개에 매달려 날아가기와는 규모가 다르다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-002665/index.html"},{"id":"MEJE-KW-002666","row_version":2,"title":"풍선을 공포의 표지로 쓰기","original":"Balloon of Doom","aliases":[],"kind":"keyword","facet_id":"ML-F20","node_kind":null,"parent_id":null,"tag_path":["ML-F20"],"summary":"축제의 풍선이 특정 악역이나 실종의 신호로 반복해 나타난다. 색과 형태는 그대로인데 등장 맥락이 안전한 이미지를 뒤집는다. 떠오르는 풍선 자체가 풍선 여러 개에 매달려 날아가기와 달리 공포의 신호가 된다.","accent":"#85835C","tab":"#9A6A55","facet":"상징·이미지","bookmark":"분류축","entry_url":"cards/MEJE-KW-002666/index.html"},{"id":"MEJE-KW-002667","row_version":2,"title":"무도회 한가운데 싸움이 터지기","original":"Ballroom Blitz","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"단정히 차려입은 사람들이 모인 행사장에 공격자나 소동이 들이닥친다. 격식 있는 춤과 피난의 움직임이 충돌한다. 술집에서 비슷한 소동이 일어나면 술집 전체가 싸움판이 되기가 된다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-002667/index.html"},{"id":"MEJE-KW-002668","row_version":1,"title":"공이라는 말의 다른 뜻으로 농담하기","original":"\"Balls\" Gag","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"둥근 물건과 행사, 신체를 가리키는 같은 말을 엮어 대화의 뜻을 바꾼다. 하나의 소리가 지닌 여러 뜻이 웃음의 장치가 된다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-002668/index.html"},{"id":"MEJE-KW-002669","row_version":1,"title":"급소 공격을 맞고도 버티기","original":"Balls of Steel","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"보통 인물을 쓰러뜨리는 충격을 받은 인물이 예상과 달리 계속 움직인다. 강인함을 과장하는 장면이지만 실제 신체의 안전 규칙과 혼동하지 않는다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-002669/index.html"},{"id":"MEJE-KW-002670","row_version":1,"title":"사슴을 무조건 순하고 불쌍하게 그리기","original":"Bambification","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":null,"parent_id":null,"tag_path":["ML-F12"],"summary":"사슴의 큰 눈과 몸짓만으로 언제나 보호받아야 할 동물이라는 이미지를 만든다. 한 동물의 다양한 행동을 순수함 하나로 줄이는 재현 관습이다.","accent":"#62816F","tab":"#9A6A55","facet":"존재·종족","bookmark":"분류축","entry_url":"cards/MEJE-KW-002670/index.html"},{"id":"MEJE-KW-002671","row_version":1,"title":"원시적 재료로 현대 기계를 흉내 내기","original":"Bamboo Technology","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":null,"parent_id":null,"tag_path":["ML-F16"],"summary":"나무와 돌, 대나무 같은 재료로 복잡한 기계의 기능을 구현한다. 기계가 어떻게 작동하는지보다 세계의 재치와 물질적 제약을 보여 준다.","accent":"#8E8263","tab":"#9A6A55","facet":"사물·도구·자원","bookmark":"분류축","entry_url":"cards/MEJE-KW-002671/index.html"},{"id":"MEJE-KW-002672","row_version":2,"title":"차 배기관을 막아 추격을 늦추기","original":"Banana in the Tailpipe","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"추격자의 차를 일시적으로 못 움직이게 하려는 장난이나 계략. 작품이 쉬운 해결책처럼 쓰더라도 실제 차량 원리의 설명으로 삼지 않는다. 과일의 다른 희극적 쓰임으로 바나나 껍질에 미끄러지기가 있다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-002672/index.html"},{"id":"MEJE-KW-002673","row_version":3,"title":"바나나 껍질에 미끄러지기","original":"Banana Peel","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"발밑의 껍질 하나가 인물을 크게 넘어뜨린다. 작은 물건과 과장된 넘어짐의 간격이 슬랩스틱의 리듬을 만든다. 바나나만으로 웃음을 예고하기이라는 기대가 작은 물건의 역할을 키운다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-002673/index.html"},{"id":"MEJE-KW-002674","row_version":1,"title":"부패한 열대 국가라는 고정관념","original":"Banana Republic","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15"],"summary":"가상의 국가를 가난하고 혼란스러우며 소수 권력자에게 지배되는 곳으로 단순화한다. 지역을 풍자의 배경으로 쓸 때 주민들의 삶과 정치의 차이를 지우지 않도록 살핀다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"분류축","entry_url":"cards/MEJE-KW-002674/index.html"},{"id":"MEJE-KW-002675","row_version":1,"title":"바나나만으로 웃음을 예고하기","original":"Bananas Are Funny","aliases":[],"kind":"keyword","facet_id":"ML-F20","node_kind":null,"parent_id":null,"tag_path":["ML-F20"],"summary":"바나나의 모양과 색, 쓰임을 장면에 넣어 곧 장난이나 미끄럼이 생길 것이라는 기대를 만든다. 익숙한 과일이 희극의 시각적 신호가 된다.","accent":"#85835C","tab":"#9A6A55","facet":"상징·이미지","bookmark":"분류축","entry_url":"cards/MEJE-KW-002675/index.html"},{"id":"MEJE-KW-002676","row_version":2,"title":"얼굴을 붕대로 가린 인물","original":"Bandaged Face","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"인물의 얼굴 대부분을 붕대로 가려 상처나 정체를 즉시 알아보기 어렵게 한다. 붕대가 보호 장치인지 숨김의 장치인지 이야기에서 정해진다. 붕대가 얼굴을 넘어서 온몸으로 번지면 온몸에 붕대를 감아 부상을 강조하기와 닮는다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-002676/index.html"},{"id":"MEJE-KW-002677","row_version":3,"title":"온몸에 붕대를 감아 부상을 강조하기","original":"Bandage Mummy","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"회복 중인 인물에게 과장될 만큼 많은 붕대를 둘러 다친 정도를 한눈에 보이게 한다. 희극과 고통의 묘사 사이에서 장면의 톤을 정한다. 심하게 다친 인물도 치료받을 때 뒤늦게 아파하기에서 뒤늦게 반응할 수 있다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-002677/index.html"},{"id":"MEJE-KW-002678","row_version":1,"title":"치료받을 때 뒤늦게 아파하기","original":"Bandage Wince","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"큰 싸움에서는 태연하던 인물이 상처를 손질하는 순간 통증에 움찔한다. 위험이 지나간 뒤 몸의 감각이 돌아오는 작은 반전이다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-002678/index.html"},{"id":"MEJE-KW-002679","row_version":2,"title":"친구들이 밴드를 만드는 회차","original":"Band Episode","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"평소 다른 일을 하던 인물들이 음악 그룹을 꾸려 연습하고 공연한다. 합주의 성공과 불화가 평소 관계를 다른 방식으로 드러낸다. 구성원이 친족이면 친척이 함께하는 음악 그룹의 관계가 공연에도 영향을 준다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-002679/index.html"},{"id":"MEJE-KW-002680","row_version":2,"title":"산간을 떠도는 도적 가족","original":"Bandit Clan","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15"],"summary":"친족 관계로 묶인 무리가 외진 길목에서 약탈을 생계와 권력으로 삼는다. 가족의 충성 규칙과 지역 사회의 두려움이 함께 설정된다. 위험을 함께 겪은 위기를 함께 넘긴 동료들의 가족 같은 유대와 혈연의 결속을 비교할 수 있다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"분류축","entry_url":"cards/MEJE-KW-002680/index.html"},{"id":"MEJE-KW-002681","row_version":1,"title":"플레이어의 물건을 훔치는 잡몹","original":"Bandit Mook","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"평범한 적처럼 나타났다가 전투 중 소지품을 빼앗고 도망친다. 피해를 되찾으려는 추격이 전투의 우선순위를 바꾼다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-002681/index.html"},{"id":"MEJE-KW-002682","row_version":2,"title":"멕시코 악당을 복식 하나로 단정하기","original":"Bandito","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"솜브레로와 망토, 억양만으로 멕시코 출신 인물을 무법자로 그린다. 특정 지역의 사람을 악역 복식으로 줄이는 정형화된 재현이다. 지역을 하나의 악역 복식으로 묶는 북아프리카 해적을 한 복식으로 단순화하기와 같은 문제를 살핀다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-002682/index.html"},{"id":"MEJE-KW-002683","row_version":2,"title":"악기와 음표로 이루어진 게임 지역","original":"Band Land","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"땅과 장애물을 악기나 악보의 형태로 꾸민 게임 공간. 음악을 듣는 경험을 발판과 움직임의 규칙으로 바꾼다. 음악의 시대 이미지를 바꾸는 현대 노래를 중세풍으로 다시 연주하기를 공간에 적용할 수도 있다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-002683/index.html"},{"id":"MEJE-KW-002684","row_version":2,"title":"성 노동자들의 보호 조직","original":"Band of Brothels","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15"],"summary":"성 노동을 하는 인물들이 안전과 협상, 정보를 위해 공동 규칙을 만든다. 개인의 취약함을 이용하는 세력과 맞서는 사회 구조로 그릴 수 있다. 그 안의 개인을 성 노동자의 삶을 노래하는 발라드의 화자로 만들 수 있다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"분류축","entry_url":"cards/MEJE-KW-002684/index.html"}]}.cards;